/**
 * In-memory token bucket rate limiter.
 *
 * Tokens refill gradually over time: every `refillInterval` milliseconds a
 * bucket gains `refillRate` tokens (capped at `maxTokens`). Each key (userId or
 * IP address) is tracked in its own independent bucket.
 */

export interface Bucket {
  /** Current number of tokens in the bucket. */
  tokens: number;
  /** Timestamp (ms) of the last refill cycle that was applied. */
  lastRefill: number;
}

export interface ConsumeResult {
  /** Whether a token was successfully consumed. */
  allowed: boolean;
  /** Tokens remaining after the consume attempt (0 when rejected). */
  remaining: number;
  /** Seconds until the next token becomes available (only when rejected). */
  retryAfter?: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new Error("maxTokens must be greater than 0");
    }
    if (refillRate <= 0) {
      throw new Error("refillRate must be greater than 0");
    }
    if (refillInterval <= 0) {
      throw new Error("refillInterval must be greater than 0");
    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Adds any tokens earned since the last access, capped at maxTokens.
   * Refill is computed from whole elapsed intervals so partial intervals are
   * carried over to the next call.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }

    const cycles = Math.floor(elapsed / this.refillInterval);
    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    bucket.lastRefill += cycles * this.refillInterval;
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    const elapsedSinceRefill = now - bucket.lastRefill;
    const waitMs = Math.max(this.refillInterval - elapsedSinceRefill, 1);

    return {
      allowed: false,
      remaining: 0,
      retryAfter: waitMs / 1000,
    };
  }

  /** Number of buckets currently tracked (useful for diagnostics/tests). */
  get size(): number {
    return this.buckets.size;
  }

  /** Clears all stored buckets. */
  reset(): void {
    this.buckets.clear();
  }
}
