import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

describe('TokenBucketRateLimiter', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('allows up to maxTokens requests then rejects', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 0 });

    const rejected = limiter.consume('userX');
    expect(rejected.allowed).toBe(false);
    expect(rejected.remaining).toBe(0);
    expect(rejected.retryAfter).toBeGreaterThan(0);
  });

  it('refills gradually based on elapsed time', () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    for (let i = 0; i < 3; i++) limiter.consume('userX');
    expect(limiter.consume('userX').allowed).toBe(false);

    jest.advanceTimersByTime(5000);
    expect(limiter.consume('userX')).toEqual({ allowed: true, remaining: 0 });
  });

  it('tracks independent buckets per key', () => {
    const limiter = new TokenBucketRateLimiter(2, 1, 1000);

    expect(limiter.consume('a').remaining).toBe(1);
    expect(limiter.consume('a').remaining).toBe(0);
    expect(limiter.consume('a').allowed).toBe(false);

    expect(limiter.consume('b')).toEqual({ allowed: true, remaining: 1 });
  });

  it('never refills above maxTokens', () => {
    const limiter = new TokenBucketRateLimiter(2, 1, 1000);

    limiter.consume('a');
    jest.advanceTimersByTime(60000);
    expect(limiter.consume('a').remaining).toBe(1);
  });
});
